-- GENERATED by `wfi generate` from data/quest/quest-0099.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [99046] = { "La messaggera perduta", "Cerca la Sentinel Eralya Leafshadow sulla strada che porta all'Oracle Glade.", "Il Council of the Forest ha mandato tempo fa un piccolo gruppo di sentinelle all'Oracle Tree. L'albero manda messaggi ai nostri anziani, e spetta a noi consegnarli sani e salvi a Darnassus.\n\nMi è giunta voce che la nostra ultima messaggera non è ancora arrivata. La frequenza dei messaggi dell'Oracle varia, ma è passato un tempo insolitamente lungo.\n\nTi prego, dirigiti verso l'Oracle Glade lungo la strada a ovest e controlla come sta. Toccava a Eralya Leafshadow, ed è ancora in addestramento. Che Elune ti guidi.", nil, "La grazia di Elune... non morirò... sola...", 0x0e4bd39c, 0x86645c27, 0xfc11cf97, nil, 0x17c4d4f1, "...m." },
  [99047] = { "Non ancora morta", "Chiedi aiuto a Byancie, a Dolanaar, per la Sentinel Eralya Leafshadow.", "Le mie sorelle e io... eravamo state mandate... Oracle Tree...\n\nAlbero... messaggio. Io... arpie... ovunque...\n\n<Eralya sputa sangue, contorcendosi dal dolore.>\n\nForse non mi resta molto... nessuno arriva. Ti prego... Byancie... a Dolanaar...", nil, "Le arpie sono state colpite dalla stessa immonda contaminazione che sta comparendo in tutta la foresta. Sono sicura che sia anche ciò che affligge la Sentinel Eralya.\n\nDobbiamo sbrigarci. Non passerà molto prima che soccomba alle sue ferite.", 0x3a868dfa, 0x445fdebf, 0x584dfcb5, nil, 0xd9ac52e3, "...m." },
  [99050] = { "Il grande albero provvede", "Raccogli $N1 Dewy Lasher Fronds, una Empty Vial e una Refreshing Spring Water per Byancie, a Dolanaar.", "Avrò bisogno del tuo aiuto per procurarmi gli ingredienti necessari a fermare il male abbastanza a lungo perché Eralya riesca a tornare qui per altre cure.\n\nPer fortuna la nostra casa vivente è ancora generosa e provvederà nel momento del bisogno.\n\nL'ingrediente principale sono le dewy lasher frond. Le troverai intorno al Lake Al'Ameth, direttamente a sud di qui, o al Wellspring Lake e al suo fiume a nord-ovest.\n\nInoltre mi serviranno una fiala vuota e un po' d'acqua di sorgente. Entrambe si possono comprare qui in città, o ottenere con uno scambio.", "Hai gli ingredienti? Temo che a Eralya non resti molto tempo.", "Grazie per il tuo aiuto. Ti prego, accetta questo per coprire il costo della fiala e dell'acqua.\n\nOra preparo l'unguento. Ci vorrà solo un momento.", 0xa032b794, 0x349f6651, 0x1904360b, 0x5b2d6269, 0xe1b52a22, "....." },
  [99053] = { "Fuga da Ban'ethil", "Aiuta la Sentinel Lynessa Duskblossom a fuggire dal Ban'ethil Barrow Den e fai sapere che è al sicuro alla Sentinel Kyra Starsong, a Dolanaar.", "Le mie preghiere sono state esaudite! Ti ringrazio per esserti <fatto/fatta> strada combattendo fin quaggiù.\n\nL'Oracle Tree mi aveva mandata qui per consegnare un messaggio ai druidi addormentati, ma ho trovato il luogo completamente invaso dai furbolg! Mi hanno teso un'imboscata prima che potessi tornare indietro e mi hanno portata quaggiù: temo di essere il loro prossimo pasto.\n\nNon so tu, ma io detesto questo posto. Sotto terra non è un luogo per i kaldorei.", nil, "Sia ringraziata Elune che c'eri tu ad aiutare Lynessa a evitare un destino oscuro con i Gnarlpine. È una delle nostre migliori, e un'amica personale.\n\nTi prego, prendi questo come ringraziamento. Che ti sia utile nel proteggere i kaldorei.", 0xd6762ffb, 0xcbcfdcbe, 0x6fd4ed25, nil, 0x6891dce3, "...m." },
  [99130] = { "Un'offerta allettante", "Raccogli $N1 Vials of Animal Blood e $N2 Duskweed Petals come esca per murloc, poi torna da Remy \"Two Times\", a Goldshire.", "Ho qualche idea su come trattare con i murloc. E una di queste aiuta anche qualcun altro nel frattempo.\n\nC'è un'erbaccia che si trova spesso nelle fattorie della zona, chiamata duskweed, e in grandi quantità i suoi petali sono tossici per la maggior parte degli animali. Se prepariamo un'esca per murloc con questa pianta, speriamo di insegnare a quelle creature a stare alla larga.\n\nE intanto qualche contadino si ritrova i campi ripuliti. Davvero un vantaggio per tutti... davvero un vantaggio per tutti.", "Trovato tutto?", "Dammi solo un minuto...\n\nÈ un'esca piuttosto semplice, ma finché nessun animale domestico ci mette il muso, dovrebbe essere sicura. Di' solo a Jason di non mangiarne.", 0x77b84f75, 0x7366f857, 0x5ab48582, 0xd1593a3f, 0x82fd44b6, "....." },
  [99158] = { "Alba tra le montagne", "Porta la cassa di candele a Father Gavin, al Misty Pine Refuge.", "Là fuori tra le montagne c'è un sacerdote che appartiene a un'organizzazione chiamata Argent Dawn. È un gruppo sacro dedito a trovare e distruggere ciò che è empio e innaturale.\n\nPadre Gavin, però, è più il tipo che cerca di aiutare e curare tutti piuttosto che impugnare un'arma. Ha sistemato un vecchio edificio come luogo di sosta per i viandanti e l'ha chiamato Misty Pine Refuge. Ho una spedizione di candele sacre da fargli avere. Potresti portargliele, se vai da quella parte?", "Perché la Luce ti ha <guidato/guidata> qui oggi?", "Ah. Candele da Ironforge.\n\nAnche se riesco perlopiù a vivere in modo indipendente nel mio eremo, ci sono alcune cose essenziali che apprezzo ricevere dalla città e dai devoti.", 0x36d4d42c, 0xa2cefc05, 0x3e817a20, 0x1e73f441, 0xba70784a, "....." },
  [99162] = { "Freddo traditore", "Raccogli i fucili dei montanari caduti.", "Anche i montanari di Ironforge devono tenere gli occhi aperti quando attraversano le vette di Dun Morogh. Neve e ghiaccio che cadono spesso segnano la fine della vita dei membri meno esperti.\n\nDopo una slavina di solito cerco qualche segno di sopravvissuti o di vittime, pregando la Luce di non trovare nulla. Ma con gli elementi così agitati, ho evitato di allontanarmi troppo. Se potessi cercare qualche montanaro disperso e portarmi i loro fucili, li riporterò a Ironforge.", "Di cosa hai bisogno?", "I montanari incidono il proprio nome sul calcio dei fucili. Aiuta a identificarli, nel caso succeda qualcosa. Li rimanderò a Ironforge: lì qualcuno li consegnerà alle famiglie.", 0x1ea8928b, 0x99bbd6c8, 0x3a1c1812, 0xece653c6, 0x49b853c2, "....." },
  [99191] = { "Una donazione di lana", nil, nil, "L'High Order accetta attualmente donazioni di wool cloth.\n\nUna donazione di sessanta pezzi di wool cloth ti farà ottenere il pieno riconoscimento dell'High Order per la tua generosità. Sessanta pezzi di lana dovrebbero bastare alle esigenze dell'High Order per ora.\n\nSe hai con te i sessanta pezzi di wool cloth e sei <pronto/pronta> a donarli, posso prenderli ora.", nil, 0xaad71c6f, nil, nil, 0xec1c7e4f, nil, ".mm.m" },
  [99192] = { "Una donazione di seta", nil, nil, nil, nil, 0xaa4c5243, nil, nil, nil, nil, ".mmmm" },
  [99196] = { "Una donazione di lana", nil, nil, "I Windshapers accettano attualmente donazioni di wool cloth.\n\nUna donazione di sessanta pezzi di wool cloth ti farà ottenere il pieno riconoscimento dei Windshapers per la tua generosità.\n\nSe hai con te i sessanta pezzi di wool cloth e sei <pronto/pronta> a donarli, posso prenderli ora.", nil, 0xaad71c6f, nil, nil, 0x23004f34, nil, ".mm.m" },
  [99197] = { "Una donazione di seta", nil, nil, nil, nil, 0xaa4c5243, nil, nil, nil, nil, ".mmmm" },
